mapper.select:
SELECT COALESCE(MAX(sort_order), 0) FROM `bitable_base_groups` WHERE deleted_at = 0
AND parent_id IS NULL
AND parent_id = #{parentId}

mapper.update:
UPDATE `bitable_base_groups` SET sort_order = CASE id
WHEN #{id} THEN #{idx}
END WHERE deleted_at = 0 AND id IN
#{id}

mapper.select:
SELECT COUNT(*)
FROM `bitable_base_groups`
WHERE deleted_at = 0
  AND name = #{name}
  AND parent_id <=> #{parentId}

  AND id != #{excludeId}
